<script lang="ts">
	import { onMount } from 'svelte';
	let asleep = $state(false);
	let line = $state('お湯がわいているよ。ゆっくりでいいよ。');
	let translation = $state('');
	let translating = $state(false);
	let translationError = $state('');
	let translatorOpen = $state(false);
	let direction = $state<'ja-en' | 'en-ja'>('ja-en');
	onMount(() => { asleep = new Date().getHours() >= 22; });
	function toggleSleep() { asleep = !asleep; }
	function swapDirection() {
		direction = direction === 'ja-en' ? 'en-ja' : 'ja-en';
		translation = '';
		translationError = '';
	}
	async function translateLine() {
		translating = true;
		translationError = '';
		translation = '';
		try {
			const response = await fetch('/api/translate', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ text: line, direction }) });
			const data = await response.json();
			if (!response.ok) throw new Error(data.error);
			translation = data.translation;
		} catch (error) {
			translationError = error instanceof Error ? error.message : 'The owl lost the words.';
		} finally {
			translating = false;
		}
	}
</script>

<svelte:head><title>Night Owl</title><meta name="theme-color" content="#172238" /></svelte:head>

<main class:asleep class:drowsy={!asleep}>
	<div class="wallpaper-glow"></div><div class="moon moon-one"></div><div class="moon moon-two"></div><div class="grain"></div>
	<header class="menubar"><div class="menu-left"><span class="apple">●</span><strong>Finder</strong><span>File</span><span>Edit</span><span>View</span><span>Go</span><span>Window</span><span>Help</span></div><div class="menu-right"><span>◉</span><span>⌁</span><span>▰</span><span>{asleep ? 'Thu 10:04 PM' : 'Thu 9:41 PM'}</span></div></header>
	<section class="desktop-note" aria-live="polite"><p>{asleep ? 'The apartment is finally quiet.' : 'The night is settling in.'}</p><h1>{asleep ? 'Do not disturb the owl.' : 'Almost bedtime.'}</h1></section>
	<div class="desktop-items" aria-hidden="true"><div class="desktop-item"><div class="folder-icon"></div><span>Tonight</span></div><div class="desktop-item"><div class="disk-icon">⌘</div><span>Macintosh HD</span></div></div>
	<section class="sleep-control"><div class="status-dot" class:active={asleep}></div><div><span class="eyebrow">OWL CLOCK</span><strong>{asleep ? 'Deep sleep mode' : 'Drowsy mode'}</strong></div><button onclick={toggleSleep} aria-pressed={asleep}>{asleep ? 'Wake gently' : "It's 10pm"}</button></section>
	{#if translatorOpen}<section class="shisa-card" aria-label="Talk to the owl"><div class="shisa-title"><span>シーサー says…</span><small>{direction === 'ja-en' ? 'Japanese → English' : 'English → Japanese'}</small></div><div class="line-input"><input bind:value={line} aria-label={direction === 'ja-en' ? 'Japanese line to translate' : 'English line to translate'} maxlength="500" onkeydown={(event) => event.key === 'Enter' && translateLine()} /><button class="swap" onclick={swapDirection} aria-label="Swap translation direction" title="Swap languages">⇄</button><button onclick={translateLine} disabled={translating}>{translating ? '…' : 'Translate'}</button></div>{#if translation}<p class="translated">{translation}</p>{:else if translationError}<p class="translate-error">{translationError}</p>{:else}<p class="translation-hint">Say a line to the owl.</p>{/if}</section>{/if}

	<section class="perch" aria-label="A sleepy owl perched on the dock">
		<div class="zzz" class:visible={asleep}><i>Z</i><i>z</i><i>z</i></div>
		<button class="owl-wrap" onclick={() => translatorOpen = !translatorOpen} aria-label="Talk to the owl" aria-expanded={translatorOpen}><svg class="owl" viewBox="0 0 310 245" role="img" aria-label="Sleeping round brown owl">
			<defs><linearGradient id="body" x1="0" x2=".8" y1="0" y2="1"><stop stop-color="#b98258"/><stop offset=".56" stop-color="#825341"/><stop offset="1" stop-color="#4c3040"/></linearGradient><linearGradient id="belly" x1=".2" y1="0" x2=".8" y2="1"><stop stop-color="#d7a172"/><stop offset="1" stop-color="#9b684f"/></linearGradient></defs>
			<ellipse cx="157" cy="220" rx="117" ry="13" fill="#192035" opacity=".34"/><path d="M64 133c-27 23-23 71 2 82 20 8 42-11 48-50z" fill="#70483f"/><path d="M243 127c27 20 26 69 3 84-21 13-45-7-52-46z" fill="#65413e"/><path d="M86 75 97 25c23 15 40 30 45 54z" fill="#875542"/><path d="m221 76-11-51c-23 14-40 30-45 54z" fill="#875542"/><path d="M71 128c0-70 31-101 84-101 53 0 85 31 85 101v62c0 28-31 38-84 38s-85-10-85-38z" fill="url(#body)"/><ellipse cx="154" cy="170" rx="58" ry="54" fill="url(#belly)" opacity=".92"/><path d="M104 89c7-21 27-31 49-25-14 10-19 25-16 44-16 2-29-4-33-19zm101 0c-7-21-27-31-49-25 14 10 19 25 16 44 16 2 29-4 33-19z" fill="#e3b27c" opacity=".8"/><path class="closed-eye" d="M98 116c13 13 30 13 43 0" fill="none" stroke="#422b34" stroke-width="6" stroke-linecap="round"/><path class="closed-eye" d="M169 116c13 13 30 13 43 0" fill="none" stroke="#422b34" stroke-width="6" stroke-linecap="round"/><path d="m155 121-10 12 10 9 10-9z" fill="#d07a4b"/><path d="M112 154c11 6 20 8 29 7M198 154c-11 6-20 8-29 7" fill="none" stroke="#754c40" stroke-width="3" stroke-linecap="round" opacity=".65"/><path d="M100 198c26 12 77 14 108 0" fill="none" stroke="#e7b482" stroke-width="3" stroke-linecap="round" opacity=".45"/><path d="M84 211c23 13 44 14 62 7M225 211c-23 13-44 14-62 7" fill="none" stroke="#3d2b37" stroke-width="5" stroke-linecap="round" opacity=".45"/></svg></button>
		<nav class="dock" aria-label="Dock"><div class="dock-icon finder">⌣</div><div class="dock-icon safari">⌁</div><div class="dock-icon messages">●</div><div class="dock-icon notes">≡</div><div class="dock-icon music">♫</div><div class="dock-divider"></div><div class="dock-icon bin">▱</div></nav>
	</section><p class="dock-caption">quietly occupying the best seat in the house</p>
</main>

<style>
	:global(*){box-sizing:border-box}:global(html,body){margin:0;min-width:320px;overflow:hidden;background:#172238;font-family:-apple-system,BlinkMacSystemFont,"SF Pro Display","Segoe UI",sans-serif}main{isolation:isolate;position:relative;height:100svh;min-height:620px;overflow:hidden;color:#ffffffdf;background:radial-gradient(ellipse at 76% 12%,#516994 0%,#2d4061 26%,#1b2b47 61%,#121d31 100%);transition:background 1.6s ease}main.asleep{background:radial-gradient(ellipse at 76% 12%,#43587d 0%,#293a59 27%,#17243c 63%,#0d1527 100%)}.wallpaper-glow{position:absolute;inset:auto -12% -35%;height:64%;z-index:-2;background:radial-gradient(ellipse,rgba(130,103,144,.34),transparent 63%);filter:blur(14px)}.moon{position:absolute;z-index:-1;border-radius:50%;background:#e8e3cd;box-shadow:0 0 40px 12px #e3e1ca29;opacity:.75}.moon-one{top:18%;left:11%;width:8px;height:8px}.moon-two{top:32%;left:22%;width:4px;height:4px;opacity:.4}.grain{pointer-events:none;position:absolute;inset:0;z-index:4;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.6'/%3E%3C/svg%3E");mix-blend-mode:soft-light}.menubar{height:34px;padding:0 15px 0 20px;display:flex;align-items:center;justify-content:space-between;background:#0e162663;border-bottom:1px solid #ffffff14;backdrop-filter:blur(18px);font-size:12px;text-shadow:0 1px 3px #111827}.menu-left,.menu-right{display:flex;align-items:center;gap:18px}.menu-left strong{font-size:13px}.apple{font-size:15px}.menu-right{gap:14px;font-size:11px}.desktop-note{position:absolute;top:17%;left:clamp(28px,8vw,128px)}.desktop-note p{margin:0 0 7px;color:#efe5d3a1;font-size:13px;letter-spacing:.04em}.desktop-note h1{margin:0;font-weight:400;font-size:clamp(24px,3vw,42px);letter-spacing:-.04em}.desktop-items{position:absolute;right:29px;top:59px;display:flex;gap:21px}.desktop-item{display:grid;justify-items:center;gap:5px;font-size:11px;text-shadow:0 1px 3px #10182a}.folder-icon{width:36px;height:28px;border-radius:4px;background:linear-gradient(#81b5e8,#3d82c9);box-shadow:inset 0 2px #fff5}.folder-icon:before{content:"";display:block;width:15px;height:5px;border-radius:4px 4px 0 0;background:#78ace0;transform:translate(2px,-3px)}.disk-icon{width:29px;height:32px;padding-top:5px;color:#5e6a77;text-align:center;border-radius:5px;background:linear-gradient(140deg,#e8edf0,#8c9aa3);font-size:18px}.sleep-control{position:absolute;left:clamp(28px,8vw,128px);bottom:14%;display:flex;gap:10px;align-items:center;padding:9px 10px 9px 12px;border:1px solid #ffffff21;border-radius:15px;background:#0e15264f;backdrop-filter:blur(12px);box-shadow:0 14px 35px #0207111f}.status-dot{width:7px;height:7px;border-radius:50%;background:#d2a073}.status-dot.active{background:#9ac5a8;box-shadow:0 0 10px #9ac5a8}.sleep-control div:nth-child(2){display:grid;gap:2px;min-width:104px}.eyebrow{font-size:8px;letter-spacing:.14em;opacity:.52}.sleep-control strong{font-size:11px;font-weight:500}.sleep-control button,.line-input button{margin-left:3px;padding:7px 10px;color:#f7f0e7;border:1px solid #ffffff29;border-radius:9px;background:#ffffff1f;font:inherit;font-size:11px;cursor:pointer;transition:.25s ease}.sleep-control button:hover,.line-input button:hover:not(:disabled){background:#ffffff38;transform:translateY(-1px)}.line-input button:disabled{opacity:.5;cursor:wait}.shisa-card{position:absolute;right:clamp(28px,5vw,72px);bottom:14%;width:280px;padding:13px;border:1px solid #ffffff21;border-radius:16px;background:#0e15264f;backdrop-filter:blur(12px);box-shadow:0 14px 35px #0207111f}.shisa-title{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:9px}.shisa-title span{font-size:12px;font-weight:600}.shisa-title small{font-size:9px;letter-spacing:.06em;opacity:.55}.line-input{