r:#13345e;background:linear-gradient(90deg,#8ed6ff 49%,#d7f2ff 50%)}.safari{background:radial-gradient(circle,#f4f3ee 0 27%,#539dd2 29% 63%,#e4e8ed 65%);color:#d24342}.messages{background:linear-gradient(145deg,#76df85,#20b44c)}.notes{background:linear-gradient(#ffd84b 0 18%,#fbfaf3 20%);color:#b8b4a6}.music{background:linear-gradient(140deg,#fe6b8a,#f13c68)}.bin{color:#8293a1;background:linear-gradient(140deg,#dbe4e8,#91a1a9)}.dock-divider{height:43px;width:1px;margin:0 3px;background:#ffffff59}.dock-caption{position:absolute;bottom:104px;left:50%;transform:translateX(-50%);z-index:2;margin:0;color:#efe5d380;font-family:Georgia,serif;font-style:italic;font-size:12px;white-space:nowrap}@keyframes breathe{0%,100%{transform:translateY(2px) scale(1,.985)}48%{transform:translateY(-2px) scale(1.028,1.024)}}@keyframes doze{0%,100%{transform:rotate(-1deg) translateY(2px)}50%{transform:rotate(1.2deg) translateY(-2px)}}@keyframes zzz{0%,100%{transform:translate(-8px,12px);opacity:0}25%,75%{opacity:.8}85%{transform:translate(10px,-20px);opacity:0}}@media(max-width:630px){main{min-height:620px}.menubar .menu-left span:not(.apple),.menubar .menu-left strong~span,.menu-right span:not(:last-child){display:none}.desktop-items{display:none}.desktop-note{top:15%}.sleep-control{bottom:190px;left:28px}.shisa-card{left:28px;right:auto;bottom:104px;width:calc(100% - 56px)}.owl-wrap{width:224px}.dock{height:68px;gap:5px;padding:7px;border-radius:19px}.dock-icon{width:43px;height:43px;border-radius:11px;font-size:23px}.dock-divider{height:34px;margin:0 1px}.zzz{right:calc(50% - 145px);top:0}.dock-caption{bottom:91px;font-size:10px}}@media(prefers-reduced-motion:reduce){.asleep .owl-wrap,.drowsy .owl-wrap,.zzz.visible{animation:none}}
